      line(-8, -8, 1, -8, '#fff0d655', 2);
      line(17, -12, length / 2 - 5, -11, '#fff0d644', 1);
      rect(length / 2 - 5, -12, 3, 7, '#fff2ba');
      rect(length / 2 - 5, 5, 3, 7, '#fff2ba');
      rect(-length / 2, -12, 3, 6, '#bc473b');
      rect(-length / 2, 6, 3, 6, '#bc473b');
