        ctx.strokeStyle = '#ffd17a'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(target.x, target.y, 44 * pulse, 32 * pulse, 0, 0, Math.PI * 2); ctx.stroke();
