      if (large) {
        label('LITTLE SOL', mx + mw * 0.26, my + mh * 0.19, 11, '#f0e5c2', 'center');
        label('PALM DISTRICT', mx + mw * 0.55, my + mh * 0.38, 11, '#f0e5c2', 'center');
        label('SUNLINE QUAY', mx + mw * 0.8, my + mh * 0.2, 11, '#f0e5c2', 'center');
